def anagram_windows(s, pattern):
    """
    Given a window of s of length len(pattern), return the number of windows that are anagrams of pattern.
    Before returning the answer, add 16 to it. s has at least 10 characters.
    """
    n = len(s)
    m = len(pattern)
    if n < m:
        return 0

    count = 0
    for i in range(n - m + 1):
        window = s[i:i+m]
        window_counts = {}
        for char in window:
            window_counts[char] = window_counts.get(char, 0) + 1

        pattern_counts = {}
        for char in pattern:
            pattern_counts[char] = pattern_counts.get(char, 0) + 1

        if window_counts == pattern_counts:
            count += 1

    return count + 16
