    Finds the length of the shortest contiguous subarray of nums with at least target multiples of 4,
    or 0 if there is none.

    Args:
        nums: A list of positive integers.
        target: A positive integer representing the target.

    Returns:
        The length of the shortest contiguous subarray with at least target multiples of 4, or 0 if none exists.
    """

    n = len(nums)
    min_len = float('inf')

    for i in range(n):
        for j in range(i, n):
            subarray = nums[i:j+1]

            for k in range(1, len(subarray) + 1):

                multiple = target % 4 == 0

                if multiple:
                    if len(subarray) >= k:
                        min_len = min(min_len, k)
                else:
                    if len(subarray) >= k:
                        min_len = min(min_len, k)

    if min_len == float('inf'):
        return 0
    else:
