    Finds the length of the longest non-empty contiguous subarray of nums
    with as many multiples of 5 as non-multiples of 5, or 0 if there is none.
    """
    max_len = 0
    for i in range(len(nums)):
        for j in range(i, len(nums)):
            sub_array = nums[i:j+1]
            num_multiples_of_5 = 0
            for num in sub_array:
                if num % 5 == 0:
                    num_multiples_of_5 += 1
                else:
                    num_multiples_of_5 = 0
            if num_multiples_of_5 == 0:
                continue
            if len(sub_array) > 0:
                is_balanced = True
                for k in range(len(sub_array) - 1):
                    if (sub_array[k] % 5 == 0 and sub_array[k+1] % 5 != 0) or \
                       (sub_array[k] % 5 != 0 and sub_array[k+1] % 5 == 0):
                        is_balanced = False
                        break
                if is_balanced:
                    max_len = max(max_len, len(sub_array))
    return max_len
